(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit22-challenge-apply-advanced"]={"id":"unit22-challenge-apply-advanced","unitId":"2-2","chapterIds":["2-2"],"unitType":"advanced","group":"2-2단원 · 3. 시장 대 줄 서기","name":"새 예시 적용 · 심화 5지선다","level":"심화","desc":"웹 수업의 핵심 논리 적용","revision":1,"originPage":"unit22","shuffleQuestions":true,"timedMode":"question","parts":[{"name":"U22-45 · 웹 적용 · 유니폼 경매","items":[{"paragraphCount":2,"readingLabel":"12문단 · 새 예시 적용","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 12문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 12문단]\n하지만 이러한 주장은 설득력이 없다. 우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다. 어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다. 시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다. 셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다. 그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.\n\n[새 적용 예시 · 원문 사례 아님]\n민준과 서진은 같은 팀 유니폼을 원한다. 민준은 가진 돈이 많아 높은 경매가를 제시했지만, 서진은 가진 돈이 적어 그 가격을 제시하지 못했다. 두 사람의 팬심 크기는 알려져 있지 않다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["정도"],"id":"U22-45-S1","type":"mc","sent":"12문단을 바탕으로 새 예시를 바르게 설명한 것은?","options":["더 비싼 값을 내겠다는 민준이 반드시 유니폼을 더 간절히 원한다.","서진은 유니폼을 소중히 여기지 않아서 높은 값을 내겠다고 하지 않았다.","경매에서 얼마까지 내겠다는지는 돈을 내고 싶은 마음만 보여 준다.","돈이 더 적은 서진이 반드시 유니폼을 더 간절히 원한다.","민준이 더 비싼 값을 내겠다고 해서 서진보다 유니폼을 더 원하는지는 알 수 없다. 서진은 가진 돈이 부족해서 높은 값을 내지 못할 수도 있다."],"answer":"민준이 더 비싼 값을 내겠다고 해서 서진보다 유니폼을 더 원하는지는 알 수 없다. 서진은 가진 돈이 부족해서 높은 값을 내지 못할 수도 있다.","why":"돈을 얼마까지 내겠다는지만 보면 유니폼을 얼마나 갖고 싶은지 정확히 알 수 없어요. 갖고 싶은 마음이 커도 가진 돈이 부족할 수 있기 때문이에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 12문단의 내용과 비교해 보세요.","choiceReviews":{"민준이 더 비싼 값을 내겠다고 해서 서진보다 유니폼을 더 원하는지는 알 수 없다. 서진은 가진 돈이 부족해서 높은 값을 내지 못할 수도 있다.":{"reason":"돈을 얼마까지 내겠다는지만 보면 유니폼을 얼마나 갖고 싶은지 정확히 알 수 없어요. 갖고 싶은 마음이 커도 가진 돈이 부족할 수 있기 때문이에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 12문단의 내용과 비교해 보세요.","edits":[]},"더 비싼 값을 내겠다는 민준이 반드시 유니폼을 더 간절히 원한다.":{"reason":"바르게 고치면: 더 비싼 값을 내겠다고 해서 민준이 유니폼을 더 간절히 원하는지는 알 수 없다.\n돈을 얼마까지 내겠다는지만 보면 유니폼을 얼마나 갖고 싶은지 정확히 알 수 없어요. 갖고 싶은 마음이 커도 가진 돈이 부족할 수 있기 때문이에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 12문단의 내용과 비교해 보세요.","edits":[{"start":8,"end":13,"before":"내겠다는 ","after":"내겠다고 해서 "},{"start":17,"end":21,"before":"반드시 ","after":""},{"start":32,"end":36,"before":"원한다.","after":"원하는지는 알 수 없다."}]},"서진은 유니폼을 소중히 여기지 않아서 높은 값을 내겠다고 하지 않았다.":{"reason":"바르게 고치면: 서진은 돈이 부족해서 높은 값을 내겠다고 하지 못했을 수도 있다.\n돈을 얼마까지 내겠다는지만 보면 유니폼을 얼마나 갖고 싶은지 정확히 알 수 없어요. 갖고 싶은 마음이 커도 가진 돈이 부족할 수 있기 때문이에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 12문단의 내용과 비교해 보세요.","edits":[{"start":4,"end":21,"before":"유니폼을 소중히 여기지 않아서 ","after":"돈이 부족해서 "},{"start":35,"end":39,"before":"않았다.","after":"못했을 수도 있다."}]},"경매에서 얼마까지 내겠다는지는 돈을 내고 싶은 마음만 보여 준다.":{"reason":"바르게 고치면: 경매에서 얼마까지 내겠다는지는 돈을 내고 싶은 마음과 실제로 낼 수 있는 돈을 함께 보여 준다.\n돈을 얼마까지 내겠다는지만 보면 유니폼을 얼마나 갖고 싶은지 정확히 알 수 없어요. 갖고 싶은 마음이 커도 가진 돈이 부족할 수 있기 때문이에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 12문단의 내용과 비교해 보세요.","edits":[{"start":26,"end":30,"before":"마음만 ","after":"마음과 실제로 낼 수 있는 돈을 함께 "}]},"돈이 더 적은 서진이 반드시 유니폼을 더 간절히 원한다.":{"reason":"바르게 고치면: 돈이 더 적다고 해서 서진이 반드시 유니폼을 더 간절히 원하는 것은 아니다.\n돈을 얼마까지 내겠다는지만 보면 유니폼을 얼마나 갖고 싶은지 정확히 알 수 없어요. 갖고 싶은 마음이 커도 가진 돈이 부족할 수 있기 때문이에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 12문단의 내용과 비교해 보세요.","edits":[{"start":5,"end":8,"before":"적은 ","after":"적다고 해서 "},{"start":27,"end":31,"before":"원한다.","after":"원하는 것은 아니다."}]}},"pageSpecificReasons":true,"evidence":{"title":"웹 적용 · 유니폼 경매","statement":"민준이 더 비싼 값을 내겠다고 해서 서진보다 유니폼을 더 원하는지는 알 수 없다. 서진은 가진 돈이 부족해서 높은 값을 내지 못할 수도 있다.","explanation":"돈을 얼마까지 내겠다는지만 보면 유니폼을 얼마나 갖고 싶은지 정확히 알 수 없어요. 갖고 싶은 마음이 커도 가진 돈이 부족할 수 있기 때문이에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 12문단의 내용과 비교해 보세요.","valid":["L12:3","L12:4","L12:5","L12:6"],"sources":[{"id":"L12","title":"줄 서기를 돈으로 살 수 있을까","label":"12문단","sentences":[{"id":"L12:1","text":"하지만 이러한 주장은 설득력이 없다.","paragraph":0,"memberIds":["L12:1"],"topic":"필자는 11문단에서 예상한 시장 옹호자의 반론, 곧 “비싼 값을 내는 사람이 공연을 가장 원하므로 시장에 맡기자”는 주장에 설득력이 없다고 본다."},{"id":"L12:2","text":"우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다.","paragraph":0,"memberIds":["L12:2"],"topic":"목표가 '모두의 만족을 최대로'라고 쳐도, 시장이 줄 서기보다 더 믿을 만하지 않을 수도 있다."},{"id":"L12:3","text":"어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다.","paragraph":0,"memberIds":["L12:3"],"topic":"돈을 많이 낸다고 해서 꼭 그걸 더 좋아한다는 뜻은 아니기 때문이다."},{"id":"L12:4","text":"시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다.","paragraph":0,"memberIds":["L12:4"],"topic":"가격에는 '얼마나 사고 싶은지(마음)'뿐 아니라 '돈이 얼마나 있는지(능력)'도 들어 있다."},{"id":"L12:5","text":"셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다.","paragraph":0,"memberIds":["L12:5"],"topic":"공연이나 경기를 가장 보고 싶은 사람도 표 살 돈이 없을 수 있다."},{"id":"L12:6","text":"그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.","paragraph":0,"memberIds":["L12:6"],"topic":"반대로, 가장 비싼 표를 산 사람이 그 공연을 별로 좋아하지 않을 수도 있다."}]}]},"editorSourceVersion":"ee924affe8ff5c3c57113304cb8779fb787a1ac8902e589abdb6d11b9e7314a8"}]},{"name":"U22-46 · 웹 적용 · 경매와 선착순","items":[{"paragraphCount":2,"readingLabel":"14문단 · 새 예시 적용","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 14문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 14문단]\n암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다. 맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다. 시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다. 그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.\n\n[새 적용 예시 · 원문 사례 아님]\n학급에서 유니폼을 나눌 방법으로 최고가 경매와 먼저 와서 기다린 사람에게 주는 선착순을 비교한다. 학생마다 가진 돈과 기다릴 수 있는 시간은 다르다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["비교"],"id":"U22-46-S1","type":"mc","sent":"14문단을 바탕으로 새 예시를 바르게 설명한 것은?","options":["경매는 돈 많은 사람에게 유리하다. 선착순도 기다릴 시간이 많은 사람에게 유리할 수 있다. 선착순이 완벽한 기준은 아니다.","경매는 돈 많은 사람에게 유리하므로 선착순은 누구에게나 완벽하게 공정하다.","선착순에는 기다릴 마음만 중요하고 기다릴 시간은 중요하지 않다.","경매에서는 실제로 낼 수 있는 돈이 중요하지만 선착순에서는 실제로 기다릴 수 있는 시간이 중요하지 않다.","선착순이 시간 많은 사람에게 유리하므로 경매는 돈 없는 사람에게도 공정하다."],"answer":"경매는 돈 많은 사람에게 유리하다. 선착순도 기다릴 시간이 많은 사람에게 유리할 수 있다. 선착순이 완벽한 기준은 아니다.","why":"돈이 많으면 경매에서 높은 값을 부르기 쉬워요. 시간이 많으면 줄을 오래 서기 쉬워요. 경매에 문제가 있다고 해서 선착순에 아무 문제가 없는 것은 아니에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 14문단의 내용과 비교해 보세요.","choiceReviews":{"경매는 돈 많은 사람에게 유리하다. 선착순도 기다릴 시간이 많은 사람에게 유리할 수 있다. 선착순이 완벽한 기준은 아니다.":{"reason":"돈이 많으면 경매에서 높은 값을 부르기 쉬워요. 시간이 많으면 줄을 오래 서기 쉬워요. 경매에 문제가 있다고 해서 선착순에 아무 문제가 없는 것은 아니에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 14문단의 내용과 비교해 보세요.","edits":[]},"경매는 돈 많은 사람에게 유리하므로 선착순은 누구에게나 완벽하게 공정하다.":{"reason":"바르게 고치면: 경매는 돈 많은 사람에게 유리하며 선착순도 시간 많은 사람에게 유리할 수 있다.\n돈이 많으면 경매에서 높은 값을 부르기 쉬워요. 시간이 많으면 줄을 오래 서기 쉬워요. 경매에 문제가 있다고 해서 선착순에 아무 문제가 없는 것은 아니에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 14문단의 내용과 비교해 보세요.","edits":[{"start":14,"end":41,"before":"유리하므로 선착순은 누구에게나 완벽하게 공정하다.","after":"유리하며 선착순도 시간 많은 사람에게 유리할 수 있다."}]},"선착순에는 기다릴 마음만 중요하고 기다릴 시간은 중요하지 않다.":{"reason":"바르게 고치면: 선착순에는 기다릴 마음과 실제로 기다릴 시간이 함께 중요하다.\n돈이 많으면 경매에서 높은 값을 부르기 쉬워요. 시간이 많으면 줄을 오래 서기 쉬워요. 경매에 문제가 있다고 해서 선착순에 아무 문제가 없는 것은 아니에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 14문단의 내용과 비교해 보세요.","edits":[{"start":10,"end":19,"before":"마음만 중요하고 ","after":"마음과 실제로 "},{"start":23,"end":35,"before":"시간은 중요하지 않다.","after":"시간이 함께 중요하다."}]},"경매에서는 실제로 낼 수 있는 돈이 중요하지만 선착순에서는 실제로 기다릴 수 있는 시간이 중요하지 않다.":{"reason":"바르게 고치면: 경매에서는 실제로 낼 수 있는 돈이 중요하고 선착순에서는 실제로 기다릴 수 있는 시간도 중요하다.\n돈이 많으면 경매에서 높은 값을 부르기 쉬워요. 시간이 많으면 줄을 오래 서기 쉬워요. 경매에 문제가 있다고 해서 선착순에 아무 문제가 없는 것은 아니에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 14문단의 내용과 비교해 보세요.","edits":[{"start":20,"end":26,"before":"중요하지만 ","after":"중요하고 "},{"start":46,"end":58,"before":"시간이 중요하지 않다.","after":"시간도 중요하다."}]},"선착순이 시간 많은 사람에게 유리하므로 경매는 돈 없는 사람에게도 공정하다.":{"reason":"바르게 고치면: 선착순은 시간 많은 사람에게 유리하고 경매도 돈 많은 사람에게 유리할 수 있다.\n돈이 많으면 경매에서 높은 값을 부르기 쉬워요. 시간이 많으면 줄을 오래 서기 쉬워요. 경매에 문제가 있다고 해서 선착순에 아무 문제가 없는 것은 아니에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 14문단의 내용과 비교해 보세요.","edits":[{"start":0,"end":5,"before":"선착순이 ","after":"선착순은 "},{"start":16,"end":26,"before":"유리하므로 경매는 ","after":"유리하고 경매도 "},{"start":28,"end":42,"before":"없는 사람에게도 공정하다.","after":"많은 사람에게 유리할 수 있다."}]}},"pageSpecificReasons":true,"evidence":{"title":"웹 적용 · 경매와 선착순","statement":"경매는 돈 많은 사람에게 유리하다. 선착순도 기다릴 시간이 많은 사람에게 유리할 수 있다. 선착순이 완벽한 기준은 아니다.","explanation":"돈이 많으면 경매에서 높은 값을 부르기 쉬워요. 시간이 많으면 줄을 오래 서기 쉬워요. 경매에 문제가 있다고 해서 선착순에 아무 문제가 없는 것은 아니에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 14문단의 내용과 비교해 보세요.","valid":["L14:1","L14:2","L14:3","L14:4"],"sources":[{"id":"L14","title":"줄 서기를 돈으로 살 수 있을까","label":"14문단","sentences":[{"id":"L14:1","text":"암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다.","paragraph":0,"memberIds":["L14:1"],"topic":"암표 거래를 옹호하는 사람들은 “줄 서기도 시간이 많은 사람에게 유리한 차별이다”라고 비판한다."},{"id":"L14:2","text":"맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다.","paragraph":0,"memberIds":["L14:2"],"topic":"필자는 그 지적을 인정한다. 다만 시장도 돈 많은 사람에게 유리하므로, 줄 서기에만 있는 문제는 아니라고 말한다."},{"id":"L14:3","text":"시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다.","paragraph":0,"memberIds":["L14:3"],"topic":"시장은 '돈 낼 마음 + 돈'으로 나눈다. 줄 서기는 '기다릴 마음 + 시간'으로 나눈다."},{"id":"L14:4","text":"그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.","paragraph":0,"memberIds":["L14:4"],"topic":"그리고 '돈을 내겠다는 마음'이 '기다리겠다는 마음'보다 더 좋은 기준이라고 볼 이유는 없다."}]}]},"editorSourceVersion":"df4bcb4c4e16d448043e121942c86edf33b13cec5f02177dc797cbb12d7676f5"}]}],"readingBlock":"challenge","readingChunk":"apply","cat":"2-2단원"};})(window);
